def run(tree):
    outfile = f"/tmp/opencode/out_{abs(hash(tree))}.json"
    res = subprocess.run([sys.executable, "-c", RUNNER, tree, "/tmp/opencode/payloads.json", outfile],
                         capture_output=True, text=True)
    if res.returncode != 0:
        print(res.stderr[-3000:]); sys.exit(1)
    return json.load(open(outfile))

